param([string]$PythonExe="",[string]$RepoRoot="D:\AssertionForge-main1",[string]$RelayUrl="https://api.highwayapi.ai/openai/chat/completions",[string]$QwenModel="qwen/qwen-2.5-72b-instruct")
$ErrorActionPreference="Stop";if(-not $PythonExe){$p=Join-Path $env:USERPROFILE ".cache\codex-runtimes\codex-primary-runtime\dependencies\python\python.exe";if(Test-Path $p){$PythonExe=$p}else{$PythonExe=(Get-Command python -ErrorAction Stop).Source}};Set-Location -LiteralPath $RepoRoot
$names=@("QWEN_API_KEY","MULTIMODEL_QWEN_PROVIDER","MULTIMODEL_QWEN_BASE_URL","MULTIMODEL_QWEN_MODEL");$old=@{};foreach($n in $names){$old[$n]=[Environment]::GetEnvironmentVariable($n,"Process")};$secure=Read-Host "Highway API key" -AsSecureString;$ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
