finally{if($ptr-ne[IntPtr]::Zero){[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr)};$key=$null;foreach($n in $names){[Environment]::SetEnvironmentVariable($n,$old[$n],"Process")}}
